from decimal import Decimal
from typing import Any


def _value(mapping: dict | None, key: str) -> Any:
    if mapping is None:
        return ""
    return mapping.get(key, "")


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table: str,
    key_col: str,
    key_value: Any,
    out_col: str,
) -> Any:
    if not tables:
        return ""

    rows = tables.get(table)
    if rows is None:
        return ""

    for row in rows:
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_col, "") == key_value:
            return row.get(out_col, "")
    return ""


def _failure(code: str, message: str) -> dict[str, str]:
    return {
        "code": code,
        "message": message,
        "severity": "BLOCK",
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    if table == "ORD_HEADER":
        # ORD-001: INSERT, UPDATE
        if event in {"INSERT", "UPDATE"}:
            discount = _number(_value(record, "DISC_PCT"))
            if not (discount >= Decimal("0") and discount <= Decimal("100")):
                errors.append(_failure("E5001", "Discount out of range"))

        # ORD-002: UPDATE
        if event == "UPDATE":
            discount = _number(_value(record, "DISC_PCT"))
            role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _value(record, "OWNER_UID"),
                "ROLE_ID",
            )
            if discount > Decimal("20") and role != "MGR" and role != "ADMIN":
                errors.append(
                    _failure(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003: UPDATE
        if event == "UPDATE":
            old_status = _value(old, "STAT_CD")
            status = _value(record, "STAT_CD")
            if old_status == "I" and status != "I" and status != "X":
                errors.append(
                    _failure(
                        "E5003",
                        "Invoiced order can only be cancelled",
                    )
                )

    elif table == "ORD_LINE":
        # ORD-004: INSERT, UPDATE
        if event in {"INSERT", "UPDATE"}:
            if not (_number(_value(record, "QTY")) > Decimal("0")):
                errors.append(_failure("E5004", "Quantity must be positive"))

        # ORD-005: INSERT
        if event == "INSERT":
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _value(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(_failure("E5005", "Product not active"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
